const PODS: PodSpec[] = [
  ...['Comet', 'Nova', 'Quasar', 'Pulsar'].map((n) => ({ scenario: halcyon, scenarioName: 'sprint-pods', sprint: 'Sprint 41', pick: { tail: `${n} Pod` } })),
