  move(scene: GraphScene, pk: string, make: (from: [number, number]) => Fx, from: [number, number], delay = 0, owner?: string, meta?: RunMeta): void {
    const prev = this.movers.get(pk);
    const wait = this.blockedFor(scene, pk, owner);
    if (wait > delay + 1e-3) {
